window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc01"]={"id": "bc01", "title": "1. 生命的分子基础", "sub": "朱圣庚《生物化学》第4版 · 第1章", "sub2": "第1章 · 89页原书版课件 + 章节测试", "modules": [{"i": 0, "name": "第1章 原书版课件（81页）", "slides": [{"i": 0, "sec": "第1章 原书版课件", "title": "生命的分子基础", "notes": "本章学习入口：先建立“生命属性→生物分子→结构/非共价作用→水/细胞→起源进化”的主线。", "img": "assets/img/bc01deck/slide-01.jpg", "points": ["BIOCHEMISTRY · CHAPTER 01", "自制教学课件 · 非老师原PPT", "按原书 8 节 / 33 个子节组织 · 适合预习、课堂讲解与复习"], "check": {"kind": "short", "id": "bc01_s1_check", "q": "本章的主线是什么？", "a": "参考要点：BIOCHEMISTRY · CHAPTER 01；自制教学课件 · 非老师原PPT；按原书 8 节 / 33 个子节组织 · 适合预习、课堂讲解与复习", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 1, "sec": "第1章 原书版课件", "title": "第1章 生命的分子基础 · 8 节 33 个子节", "notes": "先用学习地图建立全章框架。第1章不是零散概念，而是从生命属性出发，依次回答生命物质是什么、如何形成三维结构、靠什么作用稳定、水与细胞的意义，最后落到生命起源。", "img": "assets/img/bc01deck/slide-02.jpg", "points": ["8节、33个子节：先框架，后细节。", "先建立“生命属性 → 生物分子 → 三维结构 → 非共价作用 → 水 → 细胞 → 起源进化”的主线。"], "check": {"kind": "short", "id": "bc01_s2_check", "q": "本章分几节？学习顺序是什么？", "a": "参考要点：8节、33个子节：先框架，后细节。；先建立“生命属性 → 生物分子 → 三维结构 → 非共价作用 → 水 → 细胞 → 起源进化”的主线。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 2, "sec": "第1章 原书版课件", "title": "生命属性与生物化学", "notes": "本节导览：生命属性可以归纳为哪三个方面？；为什么说生物分子既复杂又同一？；自复制与自装配为什么是生命的精华？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-03.jpg", "points": ["生命属性可以归纳为哪三个方面？", "为什么说生物分子既复杂又同一？", "自复制与自装配为什么是生命的精华？"], "check": {"kind": "short", "id": "bc01_s3_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：生命属性可以归纳为哪三个方面？；为什么说生物分子既复杂又同一？；自复制与自装配为什么是生命的精华？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 3, "sec": "第1章 原书版课件", "title": "（一）化学成分复杂而同一、结构错综而有序", "notes": "这一页是本章的总纲。强调“复杂”指种类多、结构精细；“同一”指所有生物都用相似的生物分子和同一套构建逻辑。结构层次要能顺背，并区分共价键与非共价作用分别负责哪一层。", "img": "assets/img/bc01deck/slide-04.jpg", "points": ["细胞含上千种分子：水、无机离子、蛋白质、核酸、糖类、脂质。", "蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。", "生物界化学成分高度复杂，但结构模式和功能高度同一。", "结构层次：单体亚基 → 大分子 → 超分子复合体 → 细胞器 → 细胞。"], "check": {"kind": "short", "id": "bc01_s4_check", "q": "本页「（一）化学成分复杂而同一、结构错综而有序」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：细胞含上千种分子：水、无机离子、蛋白质、核酸、糖类、脂质。；蛋白质、核酸、多糖是由单体共价聚合而成的生物大分子；脂质是“准生物大分子”。；生物界化学成分高度复杂，但结构模式和功能高度同一。；结构层次：单体亚基 → 大分子 → 超分子复合体 → 细胞器 → 细胞。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 4, "sec": "第1章 原书版课件", "title": "（二）利用环境的能量和物质进行自我更新", "notes": "用“开放系统”解释生命为什么能维持有序：不是违背热力学第二定律，而是把熵增转移到环境中。强调ATP是通用能量货币，NADPH主要提供还原力。", "img": "assets/img/bc01deck/slide-05.jpg", "points": ["新陈代谢=合成代谢（同化）+分解代谢（异化）。", "代谢途径：上一步产物是下一步底物，每一步由专一酶催化。", "分解代谢释放能量，贮存于ATP、NADPH；合成代谢利用能量建造大分子。", "生物是开放系统：摄取低熵高能物质，排出低能高熵产物。"], "check": {"kind": "short", "id": "bc01_s5_check", "q": "本页「（二）利用环境的能量和物质进行自我更新」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：新陈代谢=合成代谢（同化）+分解代谢（异化）。；代谢途径：上一步产物是下一步底物，每一步由专一酶催化。；分解代谢释放能量，贮存于ATP、NADPH；合成代谢利用能量建造大分子。；生物是开放系统：摄取低熵高能物质，排出低能高熵产物。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 5, "sec": "第1章 原书版课件", "title": "（三）自我复制和自我装配是生命状态的精华", "notes": "这一页把“遗传”与“自装配”放在一起：前者保证世代之间信息连续，后者保证分子自动形成有序结构。中心法则只讲信息流，不要把它误解为所有信息都只从DNA单向流动。", "img": "assets/img/bc01deck/slide-06.jpg", "points": ["DNA是主要遗传物质：信息量大、稳定、可忠实复制。", "DNA半保留复制；突变与重组是变异和进化的分子基础。", "遗传信息表达：DNA→RNA→蛋白质；三联体密码决定氨基酸。", "自装配：亚基自发缔合成复合体，驱动力主要是疏水作用。"], "check": {"kind": "short", "id": "bc01_s6_check", "q": "本页「（三）自我复制和自我装配是生命状态的精华」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：DNA是主要遗传物质：信息量大、稳定、可忠实复制。；DNA半保留复制；突变与重组是变异和进化的分子基础。；遗传信息表达：DNA→RNA→蛋白质；三联体密码决定氨基酸。；自装配：亚基自发缔合成复合体，驱动力主要是疏水作用。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 6, "sec": "第1章 原书版课件", "title": "第1节 · 3句话 + 2题自测", "notes": "第1节收束：用三句话把生命属性、结构层次、能量与信息串起来。", "img": "assets/img/bc01deck/slide-07.jpg", "points": ["生命属性可归纳为化学成分复杂而同一、结构有序、自我更新、自我复制与自装配。", "单体通过共价键聚合成生物大分子，更高层次靠非共价作用组装。", "生命是开放系统：靠能量流维持有序，靠 DNA 复制与表达延续遗传信息。"], "check": {"kind": "short", "id": "bc01_s7_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：生命属性可归纳为化学成分复杂而同一、结构有序、自我更新、自我复制与自装配。；单体通过共价键聚合成生物大分子，更高层次靠非共价作用组装。；生命是开放系统：靠能量流维持有序，靠 DNA 复制与表达延续遗传信息。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 7, "sec": "第1章 原书版课件", "title": "第1节难点：生命属性怎么答？", "notes": "第1节难点：把生命属性从三个层面拆开，每层配一个分子例子。", "img": "assets/img/bc01deck/slide-08.jpg", "points": ["① 化学成分与结构有序；② 能量与物质自我更新；③ 自我复制与自我装配。", "生命是开放系统，靠能量流维持低熵有序。", "DNA复制保证信息连续；蛋白质执行功能；自装配形成结构。"], "check": {"kind": "short", "id": "bc01_s8_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：① 化学成分与结构有序；② 能量与物质自我更新；③ 自我复制与自我装配。；生命是开放系统，靠能量流维持低熵有序。；DNA复制保证信息连续；蛋白质执行功能；自装配形成结构。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 8, "sec": "第1章 原书版课件", "title": "生物化学与分子生物学", "notes": "本节导览：生物化学经历哪三个阶段？；分子生物学与生物化学是什么关系？；中国生物化学有哪些重要贡献？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-09.jpg", "points": ["生物化学经历哪三个阶段？", "分子生物学与生物化学是什么关系？", "中国生物化学有哪些重要贡献？"], "check": {"kind": "short", "id": "bc01_s9_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：生物化学经历哪三个阶段？；分子生物学与生物化学是什么关系？；中国生物化学有哪些重要贡献？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 9, "sec": "第1章 原书版课件", "title": "（一）现代生物化学的发展和分子生物学的兴起", "notes": "按“静态—动态—分子”三阶段讲，学生最容易记住。提醒：阶段不是截然断开，而是研究重点转移；1953年DNA双螺旋是标志性事件。", "img": "assets/img/bc01deck/slide-10.jpg", "points": ["第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。", "第二阶段（1900—1950）：动态生物化学，研究代谢途径、酶促反应与能量转化。", "第三阶段（1950—）：分子生物化学，研究生物大分子结构与功能。", "1953年DNA双螺旋模型开启分子生物学；分子生物学研究DNA、RNA、蛋白质及其关系。"], "check": {"kind": "short", "id": "bc01_s10_check", "q": "本页「（一）现代生物化学的发展和分子生物学的兴起」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：第一阶段（1770—1900）：静态/叙述生物化学，分离、纯化、测定组成与结构。；第二阶段（1900—1950）：动态生物化学，研究代谢途径、酶促反应与能量转化。；第三阶段（1950—）：分子生物化学，研究生物大分子结构与功能。；1953年DNA双螺旋模型开启分子生物学；分子生物学研究DNA、RNA、蛋白质及其关系。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 10, "sec": "第1章 原书版课件", "title": "（二）现代生物化学发展中的一些重要学术中心和学者", "notes": "人物不宜逐个背履历，抓住“贡献关键词”。Scheele—分离有机酸；Lavoisier—呼吸氧化；Liebig—代谢概念；Hoppe-Seyler—学科建立；Sumner—酶是蛋白质；Watson/Crick—双螺旋；Sanger—测序。", "img": "assets/img/bc01deck/slide-11.jpg", "points": ["Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。", "Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。", "Hoppe-Seyler：建立生理化学学科，提出“biochemie”。", "Pasteur、Fischer、Hopkins、Pavlov、Sumner 等推动微生物学、结构化学、维生素、消化生理与酶化学。"], "check": {"kind": "short", "id": "bc01_s11_check", "q": "本页「（二）现代生物化学发展中的一些重要学术中心和学者」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：Scheele：从生物材料分离柠檬酸、乳酸、尿酸、甘油等，静态生物化学开始。；Lavoisier：呼吸是缓慢氧化；Liebig：提出新陈代谢概念。；Hoppe-Seyler：建立生理化学学科，提出“biochemie”。；Pasteur、Fischer、Hopkins、Pavlov、Sumner 等推动微生物学、结构化学、维生素、消化生理与酶化学。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 11, "sec": "第1章 原书版课件", "title": "（三）发展中的我国生物化学", "notes": "这一页兼顾古代实践与现代成就。重点讲“曲”与酶的关系、牛胰岛素人工合成，既能体现学科历史，也能联系蛋白质结构与功能。", "img": "assets/img/bc01deck/slide-12.jpg", "points": ["古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。", "“曲”是促进淀粉糖化和酒化的粗酶制剂，接近现代酶的概念。", "《黄帝内经》提出“五谷为养，五畜为益，五果为助，五菜为充”。", "现代：吴宪等在蛋白质变性等方面奠基；1965年人工合成牛胰岛素。"], "check": {"kind": "short", "id": "bc01_s12_check", "q": "本页「（三）发展中的我国生物化学」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：古代发酵实践：酿酒、制醋、造酱、制饴；《齐民要术》记载制曲。；“曲”是促进淀粉糖化和酒化的粗酶制剂，接近现代酶的概念。；《黄帝内经》提出“五谷为养，五畜为益，五果为助，五菜为充”。；现代：吴宪等在蛋白质变性等方面奠基；1965年人工合成牛胰岛素。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 12, "sec": "第1章 原书版课件", "title": "第2节 · 3句话 + 2题自测", "notes": "第2节收束：按“静态—动态—分子”三阶段记忆，人物抓贡献关键词。", "img": "assets/img/bc01deck/slide-13.jpg", "points": ["现代生物化学大体经历静态、动态、分子三个阶段。", "1953 年 DNA 双螺旋模型开启分子生物学；分子生物学研究 DNA、RNA、蛋白质及其关系。", "中国学者在蛋白质变性、牛胰岛素与 tRNA 人工合成等方面作出重要贡献。"], "check": {"kind": "short", "id": "bc01_s13_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：现代生物化学大体经历静态、动态、分子三个阶段。；1953 年 DNA 双螺旋模型开启分子生物学；分子生物学研究 DNA、RNA、蛋白质及其关系。；中国学者在蛋白质变性、牛胰岛素与 tRNA 人工合成等方面作出重要贡献。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 13, "sec": "第1章 原书版课件", "title": "第2节难点：三阶段怎么记？", "notes": "第2节难点：用研究重点和标志事件记三阶段，不要背年份流水账。", "img": "assets/img/bc01deck/slide-14.jpg", "points": ["静态：组成、分离、结构；动态：代谢、酶、能量；分子：大分子与机制。", "1953 DNA双螺旋；重组DNA、测序、基因编辑。", "吴宪、牛胰岛素、tRNA人工合成。"], "check": {"kind": "short", "id": "bc01_s14_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：静态：组成、分离、结构；动态：代谢、酶、能量；分子：大分子与机制。；1953 DNA双螺旋；重组DNA、测序、基因编辑。；吴宪、牛胰岛素、tRNA人工合成。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 14, "sec": "第1章 原书版课件", "title": "生命物质的化学组成", "notes": "本节导览：生命元素如何分类？；为什么说生物分子是碳的化合物？；小分子、大分子与单体是什么关系？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-15.jpg", "points": ["生命元素如何分类？", "为什么说生物分子是碳的化合物？", "小分子、大分子与单体是什么关系？"], "check": {"kind": "short", "id": "bc01_s15_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：生命元素如何分类？；为什么说生物分子是碳的化合物？；小分子、大分子与单体是什么关系？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 15, "sec": "第1章 原书版课件", "title": "（一）生命元素", "notes": "区分“大量/微量”按含量，不按重要性；微量元素含量低但常不可替代。考试常考：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。", "img": "assets/img/bc01deck/slide-16.jpg", "points": ["大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。", "微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。", "C、H、O、N 占生物体质量绝大部分；C 是生物分子的骨架。", "大量元素构成水和有机物；微量元素多作为酶、辅酶或激素的组成成分。"], "check": {"kind": "short", "id": "bc01_s16_check", "q": "本页「（一）生命元素」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：大量元素：H、O、C、N、Ca、P、K、S、Na、Cl、Mg。；微量元素：Fe、Zn、Cu、Mn、Co、Mo、I、Se 等。；C、H、O、N 占生物体质量绝大部分；C 是生物分子的骨架。；大量元素构成水和有机物；微量元素多作为酶、辅酶或激素的组成成分。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 16, "sec": "第1章 原书版课件", "title": "（二）生物分子是碳的化合物", "notes": "强调碳的“四价”和“成链/成环”能力。官能团决定化学性质，碳骨架决定分子形状；二者共同决定生物分子功能。", "img": "assets/img/bc01deck/slide-17.jpg", "points": ["碳原子四价，可形成四个稳定共价键。", "碳链可长可短、可分支、可成环，并可连接多种官能团。", "常见官能团：羟基、羧基、氨基、磷酸基、巯基、醛/酮基。", "碳骨架的多样性 → 生物分子种类繁多、功能多样。"], "check": {"kind": "short", "id": "bc01_s17_check", "q": "本页「（二）生物分子是碳的化合物」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：碳原子四价，可形成四个稳定共价键。；碳链可长可短、可分支、可成环，并可连接多种官能团。；常见官能团：羟基、羧基、氨基、磷酸基、巯基、醛/酮基。；碳骨架的多样性 → 生物分子种类繁多、功能多样。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 17, "sec": "第1章 原书版课件", "title": "图1-1 碳原子成键的多能性", "notes": "图1-1展示碳的成键多能性。重点不是背反应式，而是理解碳能形成稳定单键、双键、三键，从而构建多样碳骨架。", "img": "assets/img/bc01deck/slide-18.jpg", "points": ["碳原子四价：可形成 4 个共价键。", "既能与 H、O、N 成键，也能与碳成键，形成 C—C、C=C、C≡C。", "单键、双键、三键的成键数目不同，决定分子的几何与反应性。", "生物分子以碳骨架为基础，但三键在生物分子中较少见。"], "imageExplain": "本页为原书配图：图1-1 碳原子成键的多能性。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s18_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：碳原子四价：可形成 4 个共价键。；既能与 H、O、N 成键，也能与碳成键，形成 C—C、C=C、C≡C。；单键、双键、三键的成键数目不同，决定分子的几何与反应性。；生物分子以碳骨架为基础，但三键在生物分子中较少见。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 18, "sec": "第1章 原书版课件", "title": "图1-2 碳成键的几何学", "notes": "图1-2把碳的几何学讲清楚：四面体、单键旋转、双键平面。它是后面构型/构象和顺反异构的基础。", "img": "assets/img/bc01deck/slide-19.jpg", "points": ["A：4 个单键指向四面体四个顶点，键角约 109.5°。", "B：C—C 单键可绕键轴自由旋转，产生不同构象。", "C：C=C 双键不能自由旋转，双键碳及相连原子共平面，键角约 120°。", "单键旋转 → 构象；双键限制旋转 → 顺反异构。"], "imageExplain": "本页为原书配图：图1-2 碳成键的几何学。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s19_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：A：4 个单键指向四面体四个顶点，键角约 109.5°。；B：C—C 单键可绕键轴自由旋转，产生不同构象。；C：C=C 双键不能自由旋转，双键碳及相连原子共平面，键角约 120°。；单键旋转 → 构象；双键限制旋转 → 顺反异构。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 19, "sec": "第1章 原书版课件", "title": "（三）生物小分子与代谢物", "notes": "把“构件”和“代谢物”两个身份讲清：同一个分子既可能是单体，也可能是代谢中间物。举例：乙酰CoA 是小分子，却是代谢枢纽。", "img": "assets/img/bc01deck/slide-20.jpg", "points": ["生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。", "代谢物是代谢途径中的中间产物和终产物。", "小分子既是生物大分子的构件，也是能量代谢和信号分子。", "单体通过共价聚合形成大分子；代谢物通过酶促反应相互转化。"], "check": {"kind": "short", "id": "bc01_s20_check", "q": "本页「（三）生物小分子与代谢物」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：生物小分子：氨基酸、核苷酸、单糖、脂肪酸、甘油等。；代谢物是代谢途径中的中间产物和终产物。；小分子既是生物大分子的构件，也是能量代谢和信号分子。；单体通过共价聚合形成大分子；代谢物通过酶促反应相互转化。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 20, "sec": "第1章 原书版课件", "title": "图1-3 生物分子中常见官能团", "notes": "图1-3是官能团总表。学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键。不要只背结构，要能判断性质。", "img": "assets/img/bc01deck/slide-21.jpg", "points": ["图1-3是官能团总表", "学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键", "不要只背结构，要能判断性质"], "check": {"kind": "short", "id": "bc01_s21_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：图1-3是官能团总表；学习时按“含氧、含氮、含硫、含磷”分组记忆，并联系极性、电荷和氢键；不要只背结构，要能判断性质", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}, "imageExplain": "本页为原书配图：图1-3 生物分子中常见官能团。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。"}, {"i": 21, "sec": "第1章 原书版课件", "title": "图1-3 局部放大（上）：含氧官能团", "notes": "图1-3上半局部：含氧官能团。放大后逐个核对名称和结构式，不要只看灰底方块。", "img": "assets/img/bc01deck/slide-22.jpg", "points": ["先看“名称—结构式”一一对应。", "重点认羟基、羰基、羧基、酯基、磷酸基。", "R 是占位基团，不代表某一种固定原子。", "含氧基团决定极性和氢键能力。"], "imageExplain": "本页为原书配图：图1-3 局部放大（上）：含氧官能团。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s22_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：先看“名称—结构式”一一对应。；重点认羟基、羰基、羧基、酯基、磷酸基。；R 是占位基团，不代表某一种固定原子。；含氧基团决定极性和氢键能力。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 22, "sec": "第1章 原书版课件", "title": "图1-3 局部放大（下）：含氮/含硫/含磷官能团", "notes": "图1-3下半局部：含氮、含硫、含磷官能团。重点区分氨基/酰胺/亚氨基，以及磷酸酐/混合酐。", "img": "assets/img/bc01deck/slide-23.jpg", "points": ["氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。", "巯基（—SH）可形成二硫键；硫酯基参与酰基转移。", "磷酸基、磷酸酐、混合酐是能量与磷酸转移的基础。", "带电基团注意正负号：—COO⁻、—NH₃⁺。"], "imageExplain": "本页为原书配图：图1-3 局部放大（下）：含氮/含硫/含磷官能团。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s23_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：氨基、酰胺基、亚氨基、胍基、咪唑基都属于含氮基团。；巯基（—SH）可形成二硫键；硫酯基参与酰基转移。；磷酸基、磷酸酐、混合酐是能量与磷酸转移的基础。；带电基团注意正负号：—COO⁻、—NH₃⁺。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 23, "sec": "第1章 原书版课件", "title": "（四）生物大分子及其单体亚基", "notes": "这一页是全章高频考点：三大类生物大分子与单体对应关系、5000这个界限、脂质的特殊地位。强调“序列决定结构，结构决定功能”。", "img": "assets/img/bc01deck/slide-24.jpg", "points": ["蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。", "生物大分子通常指相对分子质量大于5000的多聚体。", "单体排列顺序决定大分子的一级结构，进而决定高级结构和功能。", "脂质不是典型多聚体，但其聚集体具有大分子性质，称“准生物大分子”。"], "check": {"kind": "short", "id": "bc01_s24_check", "q": "本页「（四）生物大分子及其单体亚基」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：蛋白质—氨基酸；核酸—核苷酸；多糖—单糖。；生物大分子通常指相对分子质量大于5000的多聚体。；单体排列顺序决定大分子的一级结构，进而决定高级结构和功能。；脂质不是典型多聚体，但其聚集体具有大分子性质，称“准生物大分子”。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 24, "sec": "第1章 原书版课件", "title": "第3节 · 3句话 + 2题自测", "notes": "第3节收束：元素→碳骨架→小分子→大分子，层层递进。", "img": "assets/img/bc01deck/slide-25.jpg", "points": ["生命元素分大量元素与微量元素；C、H、O、N 占主要质量。", "碳四价、可成链/成环，官能团决定极性与化学反应性。", "蛋白质—氨基酸、核酸—核苷酸、多糖—单糖；生物大分子通常 M>5000。"], "check": {"kind": "short", "id": "bc01_s25_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：生命元素分大量元素与微量元素；C、H、O、N 占主要质量。；碳四价、可成链/成环，官能团决定极性与化学反应性。；蛋白质—氨基酸、核酸—核苷酸、多糖—单糖；生物大分子通常 M>5000。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 25, "sec": "第1章 原书版课件", "title": "第3节难点：从小分子到大分子", "notes": "第3节难点：用“元素→单体→大分子→超分子”四级层次组织知识。", "img": "assets/img/bc01deck/slide-26.jpg", "points": ["大量元素+微量元素；C、H、O、N为主。", "氨基酸→蛋白质；核苷酸→核酸；单糖→多糖；共价连接。", "超分子复合体→细胞器→细胞；主要靠非共价作用。"], "check": {"kind": "short", "id": "bc01_s26_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：大量元素+微量元素；C、H、O、N为主。；氨基酸→蛋白质；核苷酸→核酸；单糖→多糖；共价连接。；超分子复合体→细胞器→细胞；主要靠非共价作用。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 26, "sec": "第1章 原书版课件", "title": "生物分子的三维结构：构型与构象", "notes": "本节导览：构型与构象的本质区别是什么？；手性碳和对映体如何判断？；生物分子间的识别为什么是立体专一的？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-27.jpg", "points": ["构型与构象的本质区别是什么？", "手性碳和对映体如何判断？", "生物分子间的识别为什么是立体专一的？"], "check": {"kind": "short", "id": "bc01_s27_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：构型与构象的本质区别是什么？；手性碳和对映体如何判断？；生物分子间的识别为什么是立体专一的？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 27, "sec": "第1章 原书版课件", "title": "（一）生物分子的大小", "notes": "用数量级建立尺度感：小分子Å—nm，蛋白质nm，细胞µm。提醒学生：生物大分子不是“越大越好”，功能取决于结构和相互作用。", "img": "assets/img/bc01deck/slide-28.jpg", "points": ["小分子：相对分子质量几十到几百；生物大分子：通常 >5000。", "蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。", "核糖体、病毒、细胞器属于更大的超分子复合体。", "生物分子的大小跨越多个数量级，需用 nm—µm 尺度理解。"], "check": {"kind": "short", "id": "bc01_s28_check", "q": "本页「（一）生物分子的大小」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：小分子：相对分子质量几十到几百；生物大分子：通常 >5000。；蛋白质：约 10⁴—10⁶；核酸：可达 10⁶—10⁹。；核糖体、病毒、细胞器属于更大的超分子复合体。；生物分子的大小跨越多个数量级，需用 nm—µm 尺度理解。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 28, "sec": "第1章 原书版课件", "title": "（二）立体异构与构型", "notes": "先区分“连接次序”与“空间排列”，再讲构型。判断手性碳只看四个基团是否不同，不看碳上连了几根键。构型是“换了就回不去”的稳定空间排列。", "img": "assets/img/bc01deck/slide-29.jpg", "points": ["结构异构：原子连接次序不同。", "立体异构：连接次序相同，空间排列不同。", "构型包括对映体、非对映体和顺反异构。", "构型改变必须断裂共价键，不能靠单键旋转互变。"], "check": {"kind": "short", "id": "bc01_s29_check", "q": "本页「（二）立体异构与构型」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：结构异构：原子连接次序不同。；立体异构：连接次序相同，空间排列不同。；构型包括对映体、非对映体和顺反异构。；构型改变必须断裂共价键，不能靠单键旋转互变。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 29, "sec": "第1章 原书版课件", "title": "图1-4 立体异构体的构型", "notes": "图1-4是“构型”最重要的原图：上半部分讲顺反异构，下半部分讲对映体。要能指出哪些基团在同侧/异侧，以及D/L互为镜像。", "img": "assets/img/bc01deck/slide-30.jpg", "points": ["A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。", "A 下：顺-1,4-环己二醇与反-1,4-环己二醇，环限制旋转造成顺反差异。", "B：L(−)-甘油醛与 D(+)-甘油醛，互为镜像、不能重合，是一对对映体。", "构型改变需要断裂共价键；顺反异构和对映异构都属于构型异构。"], "imageExplain": "本页为原书配图：图1-4 立体异构体的构型。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s30_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：A 上：马来酸（顺式）与延胡索酸（反式），C=C 不能旋转造成顺反异构。；A 下：顺-1,4-环己二醇与反-1,4-环己二醇，环限制旋转造成顺反差异。；B：L(−)-甘油醛与 D(+)-甘油醛，互为镜像、不能重合，是一对对映体。；构型改变需要断裂共价键；顺反异构和对映异构都属于构型异构。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 30, "sec": "第1章 原书版课件", "title": "（三）构型的命名系统", "notes": "易错点：D/L 不是“左/右旋”，而是相对甘油醛的构型；R/S 按原子序数排优先级。L-氨基酸与D-单糖是常见记忆点。", "img": "assets/img/bc01deck/slide-31.jpg", "points": ["D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。", "L-氨基酸、D-单糖是生物体常用的构型。", "R/S 命名：按 CIP 规则给四个基团排优先级，再看空间方向。", "D/L 与 R/S 是两套独立系统，不能简单等同。"], "check": {"kind": "short", "id": "bc01_s31_check", "q": "本页「（三）构型的命名系统」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：D/L 命名：以甘油醛为参照，主要用于氨基酸和糖。；L-氨基酸、D-单糖是生物体常用的构型。；R/S 命名：按 CIP 规则给四个基团排优先级，再看空间方向。；D/L 与 R/S 是两套独立系统，不能简单等同。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 31, "sec": "第1章 原书版课件", "title": "图1-5 甘油醛的构型（D/L 命名系统）", "notes": "图1-5把Fischer式、透视式、立体模型放在同一镜面两侧，说明它们表示的是同一个构型问题。重点是会看Fischer式并判断D/L。", "img": "assets/img/bc01deck/slide-32.jpg", "points": ["同一构型可用 Fischer 投影式、透视式、立体模型表示。", "中央竖线为镜面，左右两组互为镜像，不能重合。", "Fischer 投影式：水平键朝向观察者，垂直键远离观察者。", "D/L 以甘油醛为参照；L-氨基酸、D-单糖是生物体常用构型。"], "imageExplain": "本页为原书配图：图1-5 甘油醛的构型（D/L 命名系统）。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s32_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：同一构型可用 Fischer 投影式、透视式、立体模型表示。；中央竖线为镜面，左右两组互为镜像，不能重合。；Fischer 投影式：水平键朝向观察者，垂直键远离观察者。；D/L 以甘油醛为参照；L-氨基酸、D-单糖是生物体常用构型。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 32, "sec": "第1章 原书版课件", "title": "（四）构象", "notes": "用“构型换了回不去，构象转一下还能回来”帮助记忆。蛋白质的α螺旋、β折叠都是构象/二级结构，不是构型。这个区分是考试高频易错点。", "img": "assets/img/bc01deck/slide-33.jpg", "points": ["构象：同一构型下，通过单键旋转产生的不同空间形态。", "构象改变不需要断裂共价键，通常可快速互变。", "例子：乙烷的交叉式/重叠式；蛋白质的α螺旋、β折叠。", "构象决定生物大分子的形状、活性和识别能力。"], "check": {"kind": "short", "id": "bc01_s33_check", "q": "本页「（四）构象」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：构象：同一构型下，通过单键旋转产生的不同空间形态。；构象改变不需要断裂共价键，通常可快速互变。；例子：乙烷的交叉式/重叠式；蛋白质的α螺旋、β折叠。；构象决定生物大分子的形状、活性和识别能力。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 33, "sec": "第1章 原书版课件", "title": "（五）三维结构的分子模型", "notes": "让学生建立“模型目的不同”的意识：球棍看键，空间填充看体积，飘带看折叠。结构测定方法只需知道X射线、NMR、冷冻电镜三者的基本特点。", "img": "assets/img/bc01deck/slide-34.jpg", "points": ["球棍模型：显示原子位置和化学键，适合看连接关系。", "空间填充模型：显示原子实际占据空间，适合看分子外形。", "飘带/卡通模型：显示蛋白质二级结构和折叠，适合看整体构象。", "X射线晶体学、NMR、冷冻电镜是主要结构测定方法。"], "check": {"kind": "short", "id": "bc01_s34_check", "q": "本页「（五）三维结构的分子模型」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：球棍模型：显示原子位置和化学键，适合看连接关系。；空间填充模型：显示原子实际占据空间，适合看分子外形。；飘带/卡通模型：显示蛋白质二级结构和折叠，适合看整体构象。；X射线晶体学、NMR、冷冻电镜是主要结构测定方法。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 34, "sec": "第1章 原书版课件", "title": "图1-9 三维结构的分子模型（L-丝氨酸）", "notes": "图1-9用L-丝氨酸展示四种表示方法。模型没有“谁更高级”，只是强调的信息不同：连接、键角、体积。", "img": "assets/img/bc01deck/slide-35.jpg", "points": ["透视式：用实线、楔形线、虚线表示三维朝向。", "骨架模型：只显示键线骨架，突出连接次序。", "球棍模型：球代表原子、棒代表键，突出键角和空间关系。", "空间填充模型：按范德华半径显示真实占位，突出分子外形。"], "imageExplain": "本页为原书配图：图1-9 三维结构的分子模型（L-丝氨酸）。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s35_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：透视式：用实线、楔形线、虚线表示三维朝向。；骨架模型：只显示键线骨架，突出连接次序。；球棍模型：球代表原子、棒代表键，突出键角和空间关系。；空间填充模型：按范德华半径显示真实占位，突出分子外形。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 35, "sec": "第1章 原书版课件", "title": "（六）生物分子间的相互作用是立体专一的", "notes": "从“锁钥/诱导契合”过渡到立体专一性。强调不是“形状像”就行，还要求电荷、氢键和手性匹配。药物手性例子能说明其现实意义。", "img": "assets/img/bc01deck/slide-36.jpg", "points": ["酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。", "结合位点的形状、电荷和氢键供受体必须互补。", "手性识别是生物专一性的基础：对映体生物活性常不同。", "药物对映体可能一个有效、另一个无效甚至有害。"], "check": {"kind": "short", "id": "bc01_s36_check", "q": "本页「（六）生物分子间的相互作用是立体专一的」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：酶与底物、受体与配体、抗体与抗原的结合都具有立体专一性。；结合位点的形状、电荷和氢键供受体必须互补。；手性识别是生物专一性的基础：对映体生物活性常不同。；药物对映体可能一个有效、另一个无效甚至有害。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 36, "sec": "第1章 原书版课件", "title": "第4节 · 3句话 + 2题自测", "notes": "第4节收束：先分构型/构象，再判断手性与D/L。", "img": "assets/img/bc01deck/slide-37.jpg", "points": ["构型改变需断共价键；构象改变只需单键旋转。", "手性碳连四个不同基团；对映体互为镜像、不能重合。", "D/L 以甘油醛为参照；生物体常用 L-氨基酸、D-单糖。"], "check": {"kind": "short", "id": "bc01_s37_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：构型改变需断共价键；构象改变只需单键旋转。；手性碳连四个不同基团；对映体互为镜像、不能重合。；D/L 以甘油醛为参照；生物体常用 L-氨基酸、D-单糖。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 37, "sec": "第1章 原书版课件", "title": "第4节难点：构型、构象与D/L", "notes": "第4节难点：先判断断不断键，再判断手性，最后用Fischer式定D/L。", "img": "assets/img/bc01deck/slide-38.jpg", "points": ["要断共价键→构型；只绕单键转→构象。", "连四个不同基团的碳；对映体互为镜像、不能重合。", "水平键朝前、垂直键朝后；与甘油醛比较定D/L。"], "check": {"kind": "short", "id": "bc01_s38_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：要断共价键→构型；只绕单键转→构象。；连四个不同基团的碳；对映体互为镜像、不能重合。；水平键朝前、垂直键朝后；与甘油醛比较定D/L。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 38, "sec": "第1章 原书版课件", "title": "生物系统中的非共价相互作用", "notes": "本节导览：生物系统中主要有哪四类非共价作用？；它们为什么能稳定生物大分子？；疏水作用为什么常是折叠的主要驱动力？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-39.jpg", "points": ["生物系统中主要有哪四类非共价作用？", "它们为什么能稳定生物大分子？", "疏水作用为什么常是折叠的主要驱动力？"], "check": {"kind": "short", "id": "bc01_s39_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：生物系统中主要有哪四类非共价作用？；它们为什么能稳定生物大分子？；疏水作用为什么常是折叠的主要驱动力？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 39, "sec": "第1章 原书版课件", "title": "（一）离子相互作用", "notes": "离子键本质是静电作用。注意环境：水的高介电常数会削弱静电吸引；高盐会屏蔽电荷。蛋白质盐析、离子交换层析都与离子作用有关。", "img": "assets/img/bc01deck/slide-40.jpg", "points": ["带电基团之间的静电吸引或排斥。", "蛋白质中：Asp/Glu 的 –COO⁻ 与 Lys/Arg 的 –NH₃⁺。", "DNA中：磷酸骨架的负电荷与组蛋白、Mg²⁺ 等相互作用。", "强度受介电常数、离子强度和环境 pH 影响。"], "check": {"kind": "short", "id": "bc01_s40_check", "q": "本页「（一）离子相互作用」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：带电基团之间的静电吸引或排斥。；蛋白质中：Asp/Glu 的 –COO⁻ 与 Lys/Arg 的 –NH₃⁺。；DNA中：磷酸骨架的负电荷与组蛋白、Mg²⁺ 等相互作用。；强度受介电常数、离子强度和环境 pH 影响。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 40, "sec": "第1章 原书版课件", "title": "（二）氢键", "notes": "氢键不是“氢原子之间的键”，而是H与孤对电子之间的作用。方向性使氢键具有立体专一性；G≡C三个氢键解释DNA稳定性差异。", "img": "assets/img/bc01deck/slide-41.jpg", "points": ["氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。", "具有方向性和饱和性，强度介于共价键和范德华力之间。", "DNA碱基配对：A=T 两个氢键，G≡C 三个氢键。", "蛋白质二级结构：α螺旋、β折叠靠主链氢键稳定。"], "check": {"kind": "short", "id": "bc01_s41_check", "q": "本页「（二）氢键」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：氢键：与电负性原子（N、O、F）共价结合的 H，与另一个电负性原子的孤对电子作用。；具有方向性和饱和性，强度介于共价键和范德华力之间。；DNA碱基配对：A=T 两个氢键，G≡C 三个氢键。；蛋白质二级结构：α螺旋、β折叠靠主链氢键稳定。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 41, "sec": "第1章 原书版课件", "title": "（三）范德华力", "notes": "范德华力常被忽略，但大量紧密堆积的原子间作用对结构稳定很重要。强调“距离短、数量多”的特点。", "img": "assets/img/bc01deck/slide-42.jpg", "points": ["瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。", "包括取向力、诱导力、色散力；色散力最普遍。", "作用距离很短，要求原子间紧密堆积。", "在疏水核心、分子内部堆积中贡献显著。"], "check": {"kind": "short", "id": "bc01_s42_check", "q": "本页「（三）范德华力」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：瞬时偶极诱导邻近原子产生偶极，形成微弱吸引。；包括取向力、诱导力、色散力；色散力最普遍。；作用距离很短，要求原子间紧密堆积。；在疏水核心、分子内部堆积中贡献显著。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 42, "sec": "第1章 原书版课件", "title": "（四）疏水相互作用", "notes": "这是最容易被误解的一条：疏水作用不是“油水相斥”的简单吸引，而是水分子为了维持氢键网络产生的熵驱动。用“熵驱动”四个字点明本质。", "img": "assets/img/bc01deck/slide-43.jpg", "points": ["非极性基团在水中有避水聚集的倾向。", "本质不是“非极性基团相互吸引”，而是水分子氢键网络被破坏后的熵驱动。", "蛋白质折叠时，疏水侧链埋入内部，极性侧链暴露表面。", "疏水作用是膜脂双层形成、蛋白质折叠的重要驱动力。"], "check": {"kind": "short", "id": "bc01_s43_check", "q": "本页「（四）疏水相互作用」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：非极性基团在水中有避水聚集的倾向。；本质不是“非极性基团相互吸引”，而是水分子氢键网络被破坏后的熵驱动。；蛋白质折叠时，疏水侧链埋入内部，极性侧链暴露表面。；疏水作用是膜脂双层形成、蛋白质折叠的重要驱动力。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 43, "sec": "第1章 原书版课件", "title": "（五）非共价相互作用对大分子的结构和功能是关键的", "notes": "这一页总结四类作用的分工：离子键—电荷；氢键—方向性识别；范德华—紧密堆积；疏水—折叠驱动力。强调“弱”不是缺点，而是可逆、可调控的前提。", "img": "assets/img/bc01deck/slide-44.jpg", "points": ["单个非共价作用弱，但数量多、可协同，形成稳定结构。", "它们允许生物大分子在温和条件下组装和解离。", "决定蛋白质折叠、核酸双螺旋、膜结构和分子识别。", "也是酶催化、信号转导、免疫识别的基础。"], "check": {"kind": "short", "id": "bc01_s44_check", "q": "本页「（五）非共价相互作用对大分子的结构和功能是关键的」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：单个非共价作用弱，但数量多、可协同，形成稳定结构。；它们允许生物大分子在温和条件下组装和解离。；决定蛋白质折叠、核酸双螺旋、膜结构和分子识别。；也是酶催化、信号转导、免疫识别的基础。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 44, "sec": "第1章 原书版课件", "title": "第5节 · 3句话 + 2题自测", "notes": "第5节收束：四类作用“弱而多”，是生命动态性的基础。", "img": "assets/img/bc01deck/slide-45.jpg", "points": ["四类非共价作用：离子相互作用、氢键、范德华力、疏水作用。", "单个弱、数量多、可协同；稳定三维结构并允许动态组装。", "疏水作用本质是水氢键网络的熵驱动，不是“油水相吸”。"], "check": {"kind": "short", "id": "bc01_s45_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：四类非共价作用：离子相互作用、氢键、范德华力、疏水作用。；单个弱、数量多、可协同；稳定三维结构并允许动态组装。；疏水作用本质是水氢键网络的熵驱动，不是“油水相吸”。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 45, "sec": "第1章 原书版课件", "title": "第5节难点：疏水作用为什么是熵驱动？", "notes": "第5节难点：用“水氢键网络被破坏→水熵增”解释疏水作用。", "img": "assets/img/bc01deck/slide-46.jpg", "points": ["非极性基团进入水中会破坏水—水氢键，使水分子有序化。", "聚集后减少疏水表面积，释放有序水分子。", "水分子混乱度增加，体系熵增，自由能降低，过程自发。"], "check": {"kind": "short", "id": "bc01_s46_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：非极性基团进入水中会破坏水—水氢键，使水分子有序化。；聚集后减少疏水表面积，释放有序水分子。；水分子混乱度增加，体系熵增，自由能降低，过程自发。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 46, "sec": "第1章 原书版课件", "title": "水和生命", "notes": "本节导览：水有哪些特殊性质？；水为什么是生命介质？；弱酸弱碱和缓冲如何影响生物分子？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-47.jpg", "points": ["水有哪些特殊性质？", "水为什么是生命介质？", "弱酸弱碱和缓冲如何影响生物分子？"], "check": {"kind": "short", "id": "bc01_s47_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：水有哪些特殊性质？；水为什么是生命介质？；弱酸弱碱和缓冲如何影响生物分子？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 47, "sec": "第1章 原书版课件", "title": "（一）水的结构和性质", "notes": "把“结构—性质—功能”连起来：极性→氢键→高热容/高沸点→缓冲温度、支持生命。水的高热容是重点。", "img": "assets/img/bc01deck/slide-48.jpg", "points": ["水是极性分子，O—H 键极性，分子间形成氢键。", "每个水分子最多形成4个氢键，形成动态网络。", "结果：高沸点、高熔点、高蒸发热、高热容、高表面张力。", "水的高介电常数使离子化合物易溶解。"], "check": {"kind": "short", "id": "bc01_s48_check", "q": "本页「（一）水的结构和性质」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：水是极性分子，O—H 键极性，分子间形成氢键。；每个水分子最多形成4个氢键，形成动态网络。；结果：高沸点、高熔点、高蒸发热、高热容、高表面张力。；水的高介电常数使离子化合物易溶解。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 48, "sec": "第1章 原书版课件", "title": "图1-12 水分子结构与冰中氢键", "notes": "图1-12分A、B、C三部分：先看水分子的极性，再看四面体氢键，最后看冰的三维网络。不要把B的四面体簇和C的六元环混为一谈。", "img": "assets/img/bc01deck/slide-49.jpg", "points": ["A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。", "B：冰中每个水分子与 4 个相邻水分子形成四面体氢键。", "C：水分子通过氢键连成三维网络，可看出六元环排列。", "氢键网络解释水的高热容、高沸点、高表面张力。"], "imageExplain": "本页为原书配图：图1-12 水分子结构与冰中氢键。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s49_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：A：水分子为极性分子，键角约 104.45°，有偶极矩；图中标出范德华半径与共价键长。；B：冰中每个水分子与 4 个相邻水分子形成四面体氢键。；C：水分子通过氢键连成三维网络，可看出六元环排列。；氢键网络解释水的高热容、高沸点、高表面张力。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 49, "sec": "第1章 原书版课件", "title": "（二）水是生命的介质", "notes": "水不是惰性背景，而是积极参与生命过程。强调“介质+反应物+温度缓冲”三重角色。", "img": "assets/img/bc01deck/slide-50.jpg", "points": ["水占细胞质量的大部分，是物质运输和反应的介质。", "极性分子、离子易溶于水；非极性分子难溶。", "水参与水解、水合、氧化还原等反应。", "水的流动性支持扩散、渗透和胞内运输。"], "check": {"kind": "short", "id": "bc01_s50_check", "q": "本页「（二）水是生命的介质」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：水占细胞质量的大部分，是物质运输和反应的介质。；极性分子、离子易溶于水；非极性分子难溶。；水参与水解、水合、氧化还原等反应。；水的流动性支持扩散、渗透和胞内运输。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 50, "sec": "第1章 原书版课件", "title": "（三）溶质影响水的依数性", "notes": "依数性只数“粒子数”，不数“粒子种类”。联系医学：输液必须考虑渗透压；细胞在低渗溶液中吸水胀破，在高渗溶液中皱缩。", "img": "assets/img/bc01deck/slide-51.jpg", "points": ["依数性：只与溶质粒子数有关，与粒子性质关系较小。", "包括蒸汽压下降、沸点升高、凝固点降低、渗透压。", "渗透压对细胞体积、水分分布至关重要。", "生物体通过渗透调节维持细胞内外水平衡。"], "check": {"kind": "short", "id": "bc01_s51_check", "q": "本页「（三）溶质影响水的依数性」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：依数性：只与溶质粒子数有关，与粒子性质关系较小。；包括蒸汽压下降、沸点升高、凝固点降低、渗透压。；渗透压对细胞体积、水分分布至关重要。；生物体通过渗透调节维持细胞内外水平衡。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 51, "sec": "第1章 原书版课件", "title": "（四）水、弱酸和弱碱的电离", "notes": "这一页是计算题基础。强调pH、pKa、缓冲范围三者关系；缓冲液在pKa±1范围内最有效。等电点pI是蛋白质/氨基酸净电荷为零的pH。", "img": "assets/img/bc01deck/slide-52.jpg", "points": ["水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。", "弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。", "Henderson-Hasselbalch：pH = pKa + lg([A⁻]/[HA])。", "当[A⁻]=[HA]时，pH = pKa；此时缓冲能力较强。"], "check": {"kind": "short", "id": "bc01_s52_check", "q": "本页「（四）水、弱酸和弱碱的电离」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：水可微弱电离：H₂O ⇌ H⁺ + OH⁻；pH = −lg[H⁺]。；弱酸解离：HA ⇌ H⁺ + A⁻；Ka = [H⁺][A⁻]/[HA]。；Henderson-Hasselbalch：pH = pKa + lg([A⁻]/[HA])。；当[A⁻]=[HA]时，pH = pKa；此时缓冲能力较强。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 52, "sec": "第1章 原书版课件", "title": "第6节 · 3句话 + 2题自测", "notes": "第6节收束：水结构→性质→渗透/酸碱，计算题也在这里落地。", "img": "assets/img/bc01deck/slide-53.jpg", "points": ["水是极性分子，氢键网络带来高热容、高沸点、高表面张力。", "水是溶剂、反应物/产物和温度缓冲介质；溶质影响依数性。", "pH=−lg[H⁺]；缓冲液用 pH=pKa+lg([A⁻]/[HA])；等电点时净电荷为零。"], "check": {"kind": "short", "id": "bc01_s53_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：水是极性分子，氢键网络带来高热容、高沸点、高表面张力。；水是溶剂、反应物/产物和温度缓冲介质；溶质影响依数性。；pH=−lg[H⁺]；缓冲液用 pH=pKa+lg([A⁻]/[HA])；等电点时净电荷为零。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 53, "sec": "第1章 原书版课件", "title": "第6节难点：缓冲液计算三步走", "notes": "第6节难点：缓冲液计算固定三步：方程—比值—总浓度。", "img": "assets/img/bc01deck/slide-54.jpg", "points": ["pH = pKa + lg([A⁻]/[HA])；[A⁻]=盐，[HA]=酸。", "先算比值 r=10^(pH−pKa)，再结合总浓度 x+y=C。", "x=盐浓度，y=酸浓度；检查单位与比例。"], "check": {"kind": "short", "id": "bc01_s54_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：pH = pKa + lg([A⁻]/[HA])；[A⁻]=盐，[HA]=酸。；先算比值 r=10^(pH−pKa)，再结合总浓度 x+y=C。；x=盐浓度，y=酸浓度；检查单位与比例。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 54, "sec": "第1章 原书版课件", "title": "生命的基本单位——细胞", "notes": "本节导览：生物三域如何划分？；为什么细胞是生命的基本单位？；原核细胞与真核细胞有何区别？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-55.jpg", "points": ["生物三域如何划分？", "为什么细胞是生命的基本单位？", "原核细胞与真核细胞有何区别？"], "check": {"kind": "short", "id": "bc01_s55_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：生物三域如何划分？；为什么细胞是生命的基本单位？；原核细胞与真核细胞有何区别？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 55, "sec": "第1章 原书版课件", "title": "（一）生物三域——细菌、古菌和真核生物", "notes": "三域不是“细菌、植物、动物”，而是细菌、古菌、真核。古菌常被误认为细菌，要强调其分子特征和极端环境适应性。", "img": "assets/img/bc01deck/slide-56.jpg", "points": ["三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。", "细菌和古菌是原核生物，无核膜包被的细胞核。", "古菌在分子特征上更接近真核生物，常生活在极端环境。", "真核生物有核膜、细胞核和多种膜性细胞器。"], "check": {"kind": "short", "id": "bc01_s56_check", "q": "本页「（一）生物三域——细菌、古菌和真核生物」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：三域：细菌（Bacteria）、古菌（Archaea）、真核生物（Eukarya）。；细菌和古菌是原核生物，无核膜包被的细胞核。；古菌在分子特征上更接近真核生物，常生活在极端环境。；真核生物有核膜、细胞核和多种膜性细胞器。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 56, "sec": "第1章 原书版课件", "title": "图1-15 生物三域系统树", "notes": "图1-15是无根扇状树。读图先找三个域标签，再看各域包含的类群；分支长短表示差异，不表示进化等级。", "img": "assets/img/bc01deck/slide-57.jpg", "points": ["系统树基于 rRNA 序列相似性：序列越相似，分支越接近。", "三域：细菌域、古菌域、真核生物域，共同祖先在树底部。", "细菌、古菌为原核生物；真核生物有核膜和细胞器。", "分支距离表示序列差异程度，不表示“谁更高级”。"], "imageExplain": "本页为原书配图：图1-15 生物三域系统树。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s57_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：系统树基于 rRNA 序列相似性：序列越相似，分支越接近。；三域：细菌域、古菌域、真核生物域，共同祖先在树底部。；细菌、古菌为原核生物；真核生物有核膜和细胞器。；分支距离表示序列差异程度，不表示“谁更高级”。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 57, "sec": "第1章 原书版课件", "title": "（二）细胞是所有生物的结构和功能单位", "notes": "从“边界、代谢、遗传、繁殖”四个角度说明细胞为什么是基本单位。表面积/体积比解释为什么细胞不能无限大。", "img": "assets/img/bc01deck/slide-58.jpg", "points": ["细胞是生命结构和功能的基本单位。", "单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。", "细胞膜界定边界，维持内环境相对稳定。", "细胞体积小，有利于物质交换；表面积/体积比是关键。"], "check": {"kind": "short", "id": "bc01_s58_check", "q": "本页「（二）细胞是所有生物的结构和功能单位」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：细胞是生命结构和功能的基本单位。；单细胞生物一个细胞即个体；多细胞生物由许多细胞协作。；细胞膜界定边界，维持内环境相对稳定。；细胞体积小，有利于物质交换；表面积/体积比是关键。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 58, "sec": "第1章 原书版课件", "title": "（三）原核细胞的代表——大肠杆菌", "notes": "以大肠杆菌为原核代表，记住“无核膜、拟核、70S核糖体、环状DNA、质粒”。这些也是抗生素作用靶点的背景。", "img": "assets/img/bc01deck/slide-59.jpg", "points": ["大肠杆菌：革兰氏阴性、杆状、无核膜。", "遗传物质：环状DNA，位于拟核；可有质粒。", "核糖体：70S（50S+30S），是蛋白质合成场所。", "细胞膜外有细胞壁；部分菌株有鞭毛、菌毛。"], "check": {"kind": "short", "id": "bc01_s59_check", "q": "本页「（三）原核细胞的代表——大肠杆菌」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：大肠杆菌：革兰氏阴性、杆状、无核膜。；遗传物质：环状DNA，位于拟核；可有质粒。；核糖体：70S（50S+30S），是蛋白质合成场所。；细胞膜外有细胞壁；部分菌株有鞭毛、菌毛。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 59, "sec": "第1章 原书版课件", "title": "图1-16 细菌细胞（以大肠杆菌为代表）", "notes": "图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物。左下放大框专门讲被膜三层。", "img": "assets/img/bc01deck/slide-60.jpg", "points": ["图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物", "左下放大框专门讲被膜三层"], "check": {"kind": "short", "id": "bc01_s60_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：图1-16信息量很大：先看菌体轮廓，再看拟核/质粒/核糖体，最后看被膜和表面附属物；左下放大框专门讲被膜三层", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}, "imageExplain": "本页为原书配图：图1-16 细菌细胞（以大肠杆菌为代表）。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。"}, {"i": 60, "sec": "第1章 原书版课件", "title": "（四）真核细胞含有多种膜性细胞器", "notes": "按“遗传信息—能量—合成加工—运输降解”讲细胞器，避免孤立记忆。线粒体和叶绿体有自身DNA，为内共生起源提供证据。", "img": "assets/img/bc01deck/slide-61.jpg", "points": ["细胞核：遗传信息储存、转录场所。", "线粒体：氧化磷酸化、ATP合成；有自身DNA。", "内质网：蛋白质/脂质合成与加工；粗面ER有核糖体。", "高尔基体：加工、分选和运输；溶酶体：降解。"], "check": {"kind": "short", "id": "bc01_s61_check", "q": "本页「（四）真核细胞含有多种膜性细胞器」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：细胞核：遗传信息储存、转录场所。；线粒体：氧化磷酸化、ATP合成；有自身DNA。；内质网：蛋白质/脂质合成与加工；粗面ER有核糖体。；高尔基体：加工、分选和运输；溶酶体：降解。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 61, "sec": "第1章 原书版课件", "title": "图1-17 真核细胞结构模式图", "notes": "图1-17是动物细胞与植物细胞并排。先比较细胞壁、液泡、叶绿体三项差异，再在两类细胞中找共同细胞器。", "img": "assets/img/bc01deck/slide-62.jpg", "points": ["左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。", "右：植物细胞，有细胞壁、中央大液泡、叶绿体，细胞核被液泡挤到一侧。", "叶绿体含类囊体；线粒体含嵴；高尔基体由扁平囊泡叠成。", "真核细胞有核膜和多种膜性细胞器；动物/植物细胞结构有差异。"], "imageExplain": "本页为原书配图：图1-17 真核细胞结构模式图。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。", "check": {"kind": "short", "id": "bc01_s62_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：左：动物细胞，无细胞壁，有细胞核、线粒体、内质网、高尔基体、溶酶体等。；右：植物细胞，有细胞壁、中央大液泡、叶绿体，细胞核被液泡挤到一侧。；叶绿体含类囊体；线粒体含嵴；高尔基体由扁平囊泡叠成。；真核细胞有核膜和多种膜性细胞器；动物/植物细胞结构有差异。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 62, "sec": "第1章 原书版课件", "title": "第7节 · 3句话 + 2题自测", "notes": "第7节收束：三域→细胞单位→原核代表→真核细胞器。", "img": "assets/img/bc01deck/slide-63.jpg", "points": ["三域：细菌、古菌、真核；前两者为原核，无核膜。", "细胞是结构与功能基本单位；原核有拟核、70S核糖体、质粒。", "真核有核膜和膜性细胞器；植物细胞还有细胞壁、液泡、叶绿体。"], "check": {"kind": "short", "id": "bc01_s63_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：三域：细菌、古菌、真核；前两者为原核，无核膜。；细胞是结构与功能基本单位；原核有拟核、70S核糖体、质粒。；真核有核膜和膜性细胞器；植物细胞还有细胞壁、液泡、叶绿体。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 63, "sec": "第1章 原书版课件", "title": "图1-17 局部放大：动物细胞", "notes": "图1-17左半局部：动物细胞。先找细胞核，再找线粒体、内质网、高尔基体、溶酶体。", "img": "assets/img/bc01deck/slide-64.jpg", "points": ["图1-17左半局部：动物细胞", "先找细胞核，再找线粒体、内质网、高尔基体、溶酶体"], "check": {"kind": "short", "id": "bc01_s64_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：图1-17左半局部：动物细胞；先找细胞核，再找线粒体、内质网、高尔基体、溶酶体", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}, "imageExplain": "本页为原书配图：图1-17 局部放大：动物细胞。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。"}, {"i": 64, "sec": "第1章 原书版课件", "title": "图1-17 局部放大：植物细胞", "notes": "图1-17右半局部：植物细胞。重点比较细胞壁、液泡、叶绿体与动物细胞的差异。", "img": "assets/img/bc01deck/slide-65.jpg", "points": ["图1-17右半局部：植物细胞", "重点比较细胞壁、液泡、叶绿体与动物细胞的差异"], "check": {"kind": "short", "id": "bc01_s65_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：图1-17右半局部：植物细胞；重点比较细胞壁、液泡、叶绿体与动物细胞的差异", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}, "imageExplain": "本页为原书配图：图1-17 局部放大：植物细胞。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。"}, {"i": 65, "sec": "第1章 原书版课件", "title": "第7节难点：原核与真核怎么比？", "notes": "第7节难点：用五项对比表区分原核/真核，不要只记“有没有核”。", "img": "assets/img/bc01deck/slide-66.jpg", "points": ["原核无核膜，DNA在拟核；真核有核膜包被的细胞核。", "原核只有核糖体；真核有线粒体、内质网、高尔基体、溶酶体等。", "大肠杆菌（70S核糖体、质粒、鞭毛）；酵母/植物/动物细胞。"], "check": {"kind": "short", "id": "bc01_s66_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：原核无核膜，DNA在拟核；真核有核膜包被的细胞核。；原核只有核糖体；真核有线粒体、内质网、高尔基体、溶酶体等。；大肠杆菌（70S核糖体、质粒、鞭毛）；酵母/植物/动物细胞。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 66, "sec": "第1章 原书版课件", "title": "生物分子的起源与进化", "notes": "本节导览：生物分子如何通过化学进化产生？；为什么说RNA可能是最早的基因和催化剂？；真核细胞如何从原核细胞进化而来？。先带着这些问题看后面逐页内容。", "img": "assets/img/bc01deck/slide-67.jpg", "points": ["生物分子如何通过化学进化产生？", "为什么说RNA可能是最早的基因和催化剂？", "真核细胞如何从原核细胞进化而来？"], "check": {"kind": "short", "id": "bc01_s67_check", "q": "本节要回答的核心问题有哪些？", "a": "参考要点：生物分子如何通过化学进化产生？；为什么说RNA可能是最早的基因和催化剂？；真核细胞如何从原核细胞进化而来？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 67, "sec": "第1章 原书版课件", "title": "（一）最初的生物分子是通过化学进化产生的", "notes": "区分“化学进化”和“生物进化”：前者是无机到有机、小分子到大分子；后者是细胞出现后的繁殖、变异和选择。米勒实验是经典证据，但不是生命起源的完整答案。", "img": "assets/img/bc01deck/slide-68.jpg", "points": ["早期地球：还原性大气、强紫外线、雷电、火山活动。", "无机小分子 → 有机小分子（氨基酸、核苷酸、单糖等）。", "米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。", "有机小分子在合适条件下聚合为生物大分子。"], "check": {"kind": "short", "id": "bc01_s68_check", "q": "本页「（一）最初的生物分子是通过化学进化产生的」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：早期地球：还原性大气、强紫外线、雷电、火山活动。；无机小分子 → 有机小分子（氨基酸、核苷酸、单糖等）。；米勒-尤里实验：模拟早期地球条件，可生成多种氨基酸。；有机小分子在合适条件下聚合为生物大分子。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 68, "sec": "第1章 原书版课件", "title": "（二）RNA或相关前体可能是最早的基因和催化剂", "notes": "RNA世界的核心逻辑：信息+催化双重功能，解决“先有DNA还是先有蛋白质”的循环。核酶是支持证据；要说明这是假说，不是定论。", "img": "assets/img/bc01deck/slide-69.jpg", "points": ["RNA既能贮存遗传信息，又能催化反应（核酶）。", "“RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。", "核酶的存在说明“核酸只是信息分子”不成立。", "后来DNA更适合长期贮存信息，蛋白质催化效率更高。"], "check": {"kind": "short", "id": "bc01_s69_check", "q": "本页「（二）RNA或相关前体可能是最早的基因和催化剂」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：RNA既能贮存遗传信息，又能催化反应（核酶）。；“RNA世界”假说：早期生命可能以RNA同时承担信息与催化功能。；核酶的存在说明“核酸只是信息分子”不成立。；后来DNA更适合长期贮存信息，蛋白质催化效率更高。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 69, "sec": "第1章 原书版课件", "title": "图1-19 “RNA世界”说的分子进化情景", "notes": "图1-19是8步流程图。抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化。", "img": "assets/img/bc01deck/slide-70.jpg", "points": ["图1-19是8步流程图", "抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化"], "check": {"kind": "short", "id": "bc01_s70_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：图1-19是8步流程图；抓住主线：RNA先同时承担信息和催化，随后DNA接管贮存、蛋白质接管催化", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}, "imageExplain": "本页为原书配图：图1-19 “RNA世界”说的分子进化情景。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。"}, {"i": 70, "sec": "第1章 原书版课件", "title": "（三）原始细胞的出现——生物学进化的开始", "notes": "强调“边界”的意义：没有膜，分子扩散稀释，无法形成稳定的选择单位。原始细胞不必很复杂，关键是能自我维持和复制。", "img": "assets/img/bc01deck/slide-71.jpg", "points": ["生物大分子聚集成膜包被的原始细胞（protocell）。", "膜将内部环境与外界分隔，形成相对独立的化学系统。", "原始细胞能摄取物质、进行反应、复制遗传信息。", "自然选择开始作用于可复制的原始细胞。"], "check": {"kind": "short", "id": "bc01_s71_check", "q": "本页「（三）原始细胞的出现——生物学进化的开始」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：生物大分子聚集成膜包被的原始细胞（protocell）。；膜将内部环境与外界分隔，形成相对独立的化学系统。；原始细胞能摄取物质、进行反应、复制遗传信息。；自然选择开始作用于可复制的原始细胞。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 71, "sec": "第1章 原书版课件", "title": "（四）真核细胞是从原核细胞进化而来的", "notes": "内共生学说是重点：线粒体/叶绿体有自身环状DNA、70S核糖体、双层膜，支持其细菌起源。不要把“内共生”误解为“细胞吞了一个细胞器”。", "img": "assets/img/bc01deck/slide-72.jpg", "points": ["内共生学说：线粒体源于被吞入的需氧细菌。", "叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。", "真核细胞获得高效产能和光合作用能力。", "细胞核、内膜系统、细胞骨架逐渐形成。"], "check": {"kind": "short", "id": "bc01_s72_check", "q": "本页「（四）真核细胞是从原核细胞进化而来的」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：内共生学说：线粒体源于被吞入的需氧细菌。；叶绿体源于被吞入的蓝细菌；两者都有自身DNA和双层膜。；真核细胞获得高效产能和光合作用能力。；细胞核、内膜系统、细胞骨架逐渐形成。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 72, "sec": "第1章 原书版课件", "title": "图1-20 地球上生命进化的里程碑", "notes": "图1-20是竖轴时间线，数值从下往上变小。读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆。", "img": "assets/img/bc01deck/slide-73.jpg", "points": ["图1-20是竖轴时间线，数值从下往上变小", "读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆"], "check": {"kind": "short", "id": "bc01_s73_check", "q": "按“看图顺序”，写出本图最关键的3个结构/标签，并说明它们之间的关系。", "a": "参考要点：图1-20是竖轴时间线，数值从下往上变小；读图时先看轴的方向，再按“地球形成—生命—氧气—真核—多细胞”顺序记忆", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}, "imageExplain": "本页为原书配图：图1-20 地球上生命进化的里程碑。先按右侧“看图顺序”定位整体，再用编号要点核对结构与功能。"}, {"i": 73, "sec": "第1章 原书版课件", "title": "第8节 · 3句话 + 2题自测", "notes": "第8节收束：化学进化→RNA世界→原始细胞→内共生。", "img": "assets/img/bc01deck/slide-74.jpg", "points": ["化学进化：无机小分子→有机小分子→生物大分子。", "RNA 世界：RNA 既能贮信息又能催化；后来 DNA 贮存、蛋白质催化。", "原始细胞出现后进入生物进化；内共生学说解释线粒体/叶绿体起源。"], "check": {"kind": "short", "id": "bc01_s74_check", "q": "请用三句话复述本节核心内容，并各配一个关键词。", "a": "参考要点：化学进化：无机小分子→有机小分子→生物大分子。；RNA 世界：RNA 既能贮信息又能催化；后来 DNA 贮存、蛋白质催化。；原始细胞出现后进入生物进化；内共生学说解释线粒体/叶绿体起源。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 74, "sec": "第1章 原书版课件", "title": "第8节难点：RNA世界与内共生", "notes": "第8节难点：RNA世界用“信息+催化”一条逻辑；内共生用四条证据。", "img": "assets/img/bc01deck/slide-75.jpg", "points": ["RNA既贮信息又催化→解决“先DNA还是先蛋白质”的循环。", "DNA接管贮存，蛋白质接管催化，原始细胞出现。", "线粒体/叶绿体有自身DNA、70S核糖体、双层膜、分裂方式。"], "check": {"kind": "short", "id": "bc01_s75_check", "q": "请按本页的3步拆解复述难点，并举一个例子。", "a": "参考要点：RNA既贮信息又催化→解决“先DNA还是先蛋白质”的循环。；DNA接管贮存，蛋白质接管催化，原始细胞出现。；线粒体/叶绿体有自身DNA、70S核糖体、双层膜、分裂方式。", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 75, "sec": "第1章 原书版课件", "title": "第1章 · 三条主线与高频考点", "notes": "用三条主线收束全章：生命属性、生物分子（结构/构象/非共价作用）、水与细胞及起源。让学生先能复述框架，再补细节。", "img": "assets/img/bc01deck/slide-76.jpg", "points": ["化学成分复杂而同一", "小分子/大分子/单体", "水的性质与pH/缓冲", "化学进化与RNA世界"], "check": {"kind": "short", "id": "bc01_s76_check", "q": "本页「第1章 · 三条主线与高频考点」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：化学成分复杂而同一；小分子/大分子/单体；水的性质与pH/缓冲；化学进化与RNA世界", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 76, "sec": "第1章 原书版课件", "title": "5 道题检查本章掌握度", "notes": "先让学生独立作答，再翻答案。题目只覆盖本章最基础的概念，不涉及后续章节细节。", "img": "assets/img/bc01deck/slide-77.jpg", "points": ["下列属于微量元素的是（ ）", "A. C B. H C. Fe D. O", "蛋白质的α螺旋变为β折叠属于（ ）", "A. 结构异构 B. 构型改变 C. 构象改变 D. 共价键断裂"], "check": {"kind": "short", "id": "bc01_s77_check", "q": "本页「5 道题检查本章掌握度」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：下列属于微量元素的是（ ）；A. C B. H C. Fe D. O；蛋白质的α螺旋变为β折叠属于（ ）；A. 结构异构 B. 构型改变 C. 构象改变 D. 共价键断裂", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 77, "sec": "第1章 原书版课件", "title": "课堂自测 · 答案与复习清单", "notes": "本页：课堂自测 · 答案与复习清单。结合左侧原书目录与右侧/下方讲解理解本页位置。", "img": "assets/img/bc01deck/slide-78.jpg", "points": ["课堂自测 · 答案与复习清单", "Fe 属于微量元素；C、H、O 是大量元素。", "α螺旋、β折叠都是二级结构，通过单键旋转互变，属于构象改变。", "教材以 5000 作为生物大分子的常用界限。"], "check": null}, {"i": 78, "sec": "第1章 原书版课件", "title": "附录：计算题专项", "notes": "本页导览：附录：计算题专项。结合原书目录和本节问题，先建立框架，再进入后续逐页讲解。", "img": "assets/img/bc01deck/slide-79.jpg", "points": ["APPENDIX · CALCULATION", "① 0.4 mol/L NaOH 500 mL 怎么配？", "② 浓盐酸稀释：37%、1.20 g/mL 怎么换算？", "③ 弱酸 pH=4.6，Ka、pKa 怎么求？"], "check": {"kind": "short", "id": "bc01_s79_check", "q": "写出本页最重要的公式/计算步骤，并说明单位。", "a": "参考要点：APPENDIX · CALCULATION；① 0.4 mol/L NaOH 500 mL 怎么配？；② 浓盐酸稀释：37%、1.20 g/mL 怎么换算？；③ 弱酸 pH=4.6，Ka、pKa 怎么求？", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 79, "sec": "第1章 原书版课件", "title": "计算工具箱：四个公式解决本章计算", "notes": "本章计算题核心是单位换算和守恒：n=cV、m=nM、c=1000ρw/M、pH与Henderson-Hasselbalch。先把已知量换成统一单位，再代公式。", "img": "assets/img/bc01deck/slide-80.jpg", "points": ["ρ: g/mL；w: 质量分数", "NaOH: i=2；葡萄糖: i=1", "pH = pKa + lg([A⁻]/[HA])"], "check": {"kind": "short", "id": "bc01_s80_check", "q": "写出本页最重要的公式/计算步骤，并说明单位。", "a": "参考要点：ρ: g/mL；w: 质量分数；NaOH: i=2；葡萄糖: i=1；pH = pKa + lg([A⁻]/[HA])", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 80, "sec": "第1章 原书版课件", "title": "例题：溶液配制、pH 与缓冲液", "notes": "例1强调配制与稀释：先求物质的量，再换算质量或体积。例2强调pH、Ka和缓冲液：先写平衡式/方程，再代入数据；缓冲液还可用总浓度守恒解方程组。", "img": "assets/img/bc01deck/slide-81.jpg", "points": ["例1 NaOH 与浓盐酸稀释", "① 0.4 mol/L NaOH 500 mL", "n=0.4×0.500=0.20 mol", "m=0.20×40=8.0 g"], "check": {"kind": "short", "id": "bc01_s81_check", "q": "本页「例题：溶液配制、pH 与缓冲液」的核心要点是什么？请写出至少3点，并解释其中一点。", "a": "参考要点：例1 NaOH 与浓盐酸稀释；① 0.4 mol/L NaOH 500 mL；n=0.4×0.500=0.20 mol；m=0.20×40=8.0 g", "e": "答案要点来自本页PPT；先自己写，再展开对照。", "src": "本页自测"}}, {"i": 81, "sec": "原书课后题", "title": "附录C：原书课后题", "notes": "12道原书课后题：3道概念题、1道应用/手性题、1道综合比较题、1道水性质题、6道计算题。", "img": "assets/img/bc01deck/slide-82.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 82, "sec": "原书课后题", "title": "第1题", "notes": "先定义，再按三阶段，最后说关系。", "img": "assets/img/bc01deck/slide-83.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 83, "sec": "原书课后题", "title": "第2题", "notes": "答“选择原因 + 碳优势 + 硅局限”三点。", "img": "assets/img/bc01deck/slide-84.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 84, "sec": "原书课后题", "title": "第3—4题", "notes": "Q3 抓“酶立体专一性”；Q4 抓“消旋体=等量对映体”。", "img": "assets/img/bc01deck/slide-85.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 85, "sec": "原书课后题", "title": "第5—6题", "notes": "Q5 按“本质—特点—例子”比较四类作用；Q6 抓“断氢键耗能”。", "img": "assets/img/bc01deck/slide-86.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 86, "sec": "原书课后题", "title": "第7—8题", "notes": "Q7 注意 500 mL=0.500 L、NaOH 粒子数 i=2；Q8 先换算浓盐酸浓度。", "img": "assets/img/bc01deck/slide-87.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 87, "sec": "原书课后题", "title": "第9—10题", "notes": "Q9 弱酸近似 Ka≈[H⁺]²/c；Q10 找“多一个质子”的物种。", "img": "assets/img/bc01deck/slide-88.jpg", "points": [], "check": null, "imageExplain": ""}, {"i": 88, "sec": "原书课后题", "title": "第11—12题", "notes": "Q11 盐/酸不要代反；Q12 先求比值，再用总浓度解方程。", "img": "assets/img/bc01deck/slide-89.jpg", "points": [], "check": null, "imageExplain": ""}]}], "mcq": [{"id": "bc01_exam_mcq1", "modI": 0, "q": "下列元素中，属于生物体微量元素的是？", "o": ["A. 碳", "B. 氢", "C. 铁", "D. 氧"], "a": "C", "e": "Fe属于微量元素；C、H、O是大量元素。", "oe": ["碳是大量元素。", "氢是大量元素。", "铁在生物体中含量很低，是微量元素。", "氧是大量元素。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq2", "modI": 0, "q": "生物大分子通常指相对分子质量大于多少的多聚体？", "o": ["A. 500", "B. 1000", "C. 5000", "D. 50000"], "a": "C", "e": "教材中生物大分子一般指相对分子质量大于5000的多聚体，如蛋白质、核酸、多糖。", "oe": ["500太小。", "1000仍偏小。", "5000是常用界限。", "50000不是通用界限。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq3", "modI": 0, "q": "蛋白质、核酸和多糖的单体依次是？", "o": ["A. 氨基酸、核苷酸、单糖", "B. 单糖、氨基酸、核苷酸", "C. 核苷酸、单糖、氨基酸", "D. 脂肪酸、氨基酸、核苷酸"], "a": "A", "e": "蛋白质由氨基酸组成，核酸由核苷酸组成，多糖由单糖组成。", "oe": ["顺序正确。", "单糖是多糖单体，不是蛋白质单体。", "核苷酸是核酸单体。", "脂肪酸不是蛋白质的单体。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq4", "modI": 0, "q": "蛋白质的α螺旋变为β折叠，属于哪种变化？", "o": ["A. 结构异构", "B. 构型改变", "C. 构象改变", "D. 共价键断裂"], "a": "C", "e": "α螺旋和β折叠都是二级结构，通过单键旋转互变，不涉及共价键断裂，属于构象改变。", "oe": ["结构异构是原子连接次序不同。", "构型改变需要断裂共价键。", "构象改变只需单键旋转，α螺旋/β折叠属于此类。", "没有共价键断裂。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq5", "modI": 0, "q": "一对对映体之间的关系是？", "o": ["A. 互为镜像且能重合", "B. 互为镜像但不能重合", "C. 结构完全相同", "D. 连接次序不同"], "a": "B", "e": "对映体互为镜像但不能重合，物理性质基本相同，旋光方向相反，生物活性可不同。", "oe": ["镜像分子不能重合。", "正确：镜像、不能重合。", "不是完全相同。", "连接次序相同，空间构型不同。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq6", "modI": 0, "q": "蛋白质折叠中，把非极性侧链聚集到内部的主要作用力是？", "o": ["A. 离子键", "B. 氢键", "C. 疏水作用", "D. 二硫键"], "a": "C", "e": "非极性侧链避水聚集，主要由疏水作用（熵驱动）推动，是蛋白质折叠的重要驱动力。", "oe": ["离子键发生在带电基团间。", "氢键主要稳定二级结构。", "疏水作用把非极性基团聚集到内部。", "二硫键是共价交联，不是主要折叠驱动力。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq7", "modI": 0, "q": "水具有高热容，主要原因是？", "o": ["A. 水分子很小", "B. 水分子间形成大量氢键", "C. 水不含碳", "D. 水是中性分子"], "a": "B", "e": "水分子间形成大量氢键，加热时部分能量用于断氢键，因此温度升高所需热量大。", "oe": ["分子小不是主要原因。", "氢键网络吸收热量，导致高热容。", "是否含碳与热容无关。", "中性不是高热容的原因。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}, {"id": "bc01_exam_mcq8", "modI": 0, "q": "缓冲液中[A−]=[HA]时，pH等于？", "o": ["A. pKa", "B. 7.0", "C. pI", "D. 0"], "a": "A", "e": "Henderson-Hasselbalch方程pH=pKa+lg([A−]/[HA])；当[A−]=[HA]时，lg1=0，pH=pKa。", "oe": ["正确：pH=pKa。", "pH7只在中性缓冲时接近。", "pI是等电点，不是缓冲对pKa。", "pH0是强酸性。"], "kp": "", "freq": "期末风格", "prio": "A", "req": "掌握"}], "judge": [{"id": "bc01_exam_judge1", "modI": 0, "q": "微量元素在生物体中含量很低，但仍是生命活动必需的。", "a": "对", "e": "Fe、Zn、Cu、Mn等微量元素含量低，但参与酶、辅酶等，必需。", "kp": ""}, {"id": "bc01_exam_judge2", "modI": 0, "q": "对映体的物理性质完全相同，生物活性也完全相同。", "a": "错", "e": "对映体物理性质基本相同，但生物活性常不同，酶和受体具有手性识别。", "kp": ""}, {"id": "bc01_exam_judge3", "modI": 0, "q": "构象改变需要断裂共价键。", "a": "错", "e": "构象改变只需单键旋转；构型改变才涉及共价键断裂。", "kp": ""}, {"id": "bc01_exam_judge4", "modI": 0, "q": "水的高热容与分子间氢键有关。", "a": "对", "e": "水分子间大量氢键吸收热量，使水具有高热容。", "kp": ""}, {"id": "bc01_exam_judge5", "modI": 0, "q": "原核细胞没有核膜包被的细胞核。", "a": "对", "e": "原核细胞只有拟核，无核膜包被的细胞核。", "kp": ""}], "fill": [{"id": "bc01_exam_fill1", "modI": 0, "q": "生物大分子通常指相对分子质量大于______的多聚体。", "a": "5000", "e": "教材常用5000作为生物大分子的界限。", "kp": ""}, {"id": "bc01_exam_fill2", "modI": 0, "q": "蛋白质的基本构件是______。", "a": "氨基酸", "e": "蛋白质由氨基酸聚合而成。", "kp": ""}, {"id": "bc01_exam_fill3", "modI": 0, "q": "核酸的基本构件是______。", "a": "核苷酸", "e": "核酸由核苷酸聚合而成。", "kp": ""}, {"id": "bc01_exam_fill4", "modI": 0, "q": "多糖的基本构件是______。", "a": "单糖", "e": "多糖由单糖聚合而成。", "kp": ""}, {"id": "bc01_exam_fill5", "modI": 0, "q": "水的高热容主要与分子间______有关。", "a": "氢键", "e": "水分子间形成大量氢键，吸收热量。", "kp": ""}], "term": [{"id": "bc01_exam_term1", "modI": 0, "term": "生命元素", "def": "组成生物体所必需的化学元素，分为大量元素和微量元素。", "kps": "大量/微量元素+必需", "kp": ""}, {"id": "bc01_exam_term2", "modI": 0, "term": "生物大分子", "def": "由单体聚合而成、相对分子质量通常大于5000的高分子，如蛋白质、核酸、多糖。", "kps": "单体聚合+M>5000", "kp": ""}, {"id": "bc01_exam_term3", "modI": 0, "term": "构型", "def": "分子中原子或基团的空间排列方式，改变构型需要断裂共价键，如D/L、顺反异构。", "kps": "空间排列+需断键", "kp": ""}, {"id": "bc01_exam_term4", "modI": 0, "term": "构象", "def": "分子通过单键旋转产生的不同空间形态，不涉及共价键断裂，如α螺旋、β折叠。", "kps": "单键旋转+不断键", "kp": ""}, {"id": "bc01_exam_term5", "modI": 0, "term": "对映体", "def": "互为镜像但不能重合的一对立体异构体，旋光方向相反，生物活性可不同。", "kps": "镜像+不能重合+旋光相反", "kp": ""}], "short": [{"id": "bc01_short_1", "modI": 0, "q": "生物化学研究什么？它作为一门学科是怎样发展起来的？它与分子生物学有什么关系？", "a": "(1) 生物化学研究生命属性的化学本质，包括生物分子的结构与功能、物质代谢与调节、遗传信息传递与表达等。\n(2) 现代生物化学大体经历三个阶段：静态/叙述生物化学（1770—1900，研究组成、分离、结构）→ 动态生物化学（1900—1950，研究代谢、酶、能量）→ 分子生物化学（1950年以后，研究大分子结构与分子机制）。\n(3) 分子生物学是生物化学发展的新阶段，研究DNA、RNA、蛋白质等生物大分子及其相互关系。", "kps": "研究内容1分；三阶段各1分；与分子生物学关系1分", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "先答定义，再按“静态—动态—分子”三阶段，最后说二者关系；不要只写年份。"}, {"id": "bc01_short_2", "modI": 0, "q": "进化过程中生命元素是怎样被选择的？硅和碳同为IVA族、都能形成4个单键，为什么硅没有成为生命骨架？", "a": "(1) 生命元素的选择与环境中原料的可得性有关，也取决于元素及其化合物对生命过程特殊作用的适合性。\n(2) 碳能形成稳定的C—C单键、双键和三键，可构成链状、分支和环状骨架；CO₂溶于水，有利于碳循环。\n(3) 硅原子较大，Si—Si键比C—C弱，Si的多聚物遇水不稳定，SiO₂难溶于水，不利于在需氧环境中循环，因此硅只以痕量存在。", "kps": "元素选择两个原因；C与Si比较：成键、稳定性、溶解性、循环", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "答“选择原因+碳的优势+硅的局限”三点；不要只说“碳是生命元素”。"}, {"id": "bc01_short_3", "modI": 0, "q": "原始生物分子有立体异构体时，为什么生物几乎只利用一种异构体（如L-氨基酸、D-单糖）？", "a": "现有观点认为：酶对底物具有立体专一性。生命起源后，具有选择性的酶和蛋白质逐步进化；代谢反应几乎都由酶催化，酶只与特定构型的底物结合，因此生物体优先利用一种对映体。", "kps": "关键：酶对底物的立体专一性；不是化学合成偏倚", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "关键词是“酶促反应的立体专一性”，不是“另一种不存在”。"}, {"id": "bc01_short_4", "modI": 0, "q": "苯丙胺（benzedrine）是消旋体，右旋苯丙胺（dexedrine）是单一活性对映体。为什么达到同样效应，消旋体所需剂量约为右旋体的2倍？", "a": "该药物含一个手性碳，有一对对映体。右旋体（dexedrine）是主要活性形式；消旋体（benzedrine）中只有一半是右旋体，另一半左旋体活性很低，因此要达到同样生理效应，消旋体剂量约为右旋体的2倍。", "kps": "手性碳；对映体；消旋体只有一半活性；剂量差2倍", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "核心：消旋体=等量对映体，只有一种有高活性。"}, {"id": "bc01_short_5", "modI": 0, "q": "生物分子间和分子内的非共价相互作用有哪些？它们有什么区别？", "a": "主要包括离子相互作用、氢键、范德华力和疏水作用。\n(1) 离子相互作用：带电基团间的静电吸引，受盐浓度和介电常数影响。\n(2) 氢键：H与N/O/F孤对电子作用，有方向性和饱和性。\n(3) 范德华力：瞬时偶极诱导，作用距离短，要求紧密堆积。\n(4) 疏水作用：非极性基团避水聚集，本质是水氢键网络的熵驱动。", "kps": "四类非共价作用；每类特点：键能、方向性、饱和性、距离依赖", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "四类作用按“本质—特点—例子”比较；疏水作用不是一种吸引键。"}, {"id": "bc01_short_6", "modI": 0, "q": "解释为什么水分子之间形成氢键会造成高比热容。", "a": "水分子间形成大量氢键，构成动态氢键网络。加热时，一部分能量用于断裂氢键，而不是全部用于增加分子动能，因此使水温升高需要较多热量，表现为高比热容。氢键还具有协同性，使水的内聚力较大。", "kps": "水的极性/氢键；氢键网络；吸热用于断氢键", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "关键词：氢键网络、断氢键耗能、温度升高慢。"}, {"id": "bc01_short_7", "modI": 0, "q": "【计算】配制 0.4 mol/L NaOH 溶液 500 mL：(1) 需要多少克固体 NaOH？(2) 用质量浓度（g/L）和摩尔渗透压浓度表示该溶液。", "a": "(1) n=cV=0.4 mol/L×0.500 L=0.20 mol；m=nM=0.20 mol×40 g/mol=8.0 g。\n(2) 质量浓度=8.0 g÷0.500 L=16 g/L；NaOH 完全解离为 Na⁺ 和 OH⁻，粒子总浓度=2×0.4=0.8 mol/L，故摩尔渗透压浓度=0.8 mol/L（即 0.8 osmol/L）。", "kps": "n=cV；m=nM；质量浓度=m/V；渗透压浓度=粒子数×摩尔浓度", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "先算物质的量，再算质量；质量浓度用“溶质质量÷溶液体积”；渗透压浓度要乘粒子数。注意 500 mL=0.500 L。"}, {"id": "bc01_short_8", "modI": 0, "q": "【计算】配制 0.5 mol/L 盐酸 2000 mL，需要量取浓盐酸（质量分数 37%，密度 1.20 g/mL）多少 mL？", "a": "浓盐酸的物质的量浓度：c=1000ρw/M=1000×1.20×0.37÷36.5≈12.16 mol/L。\n所需 HCl：n=cV=0.5 mol/L×2.00 L=1.00 mol。\n所需浓盐酸体积：V=n/c=1.00 mol÷12.16 mol/L≈0.0822 L=82.2 mL。", "kps": "c=1000ρw/M；稀释前后n不变；V=n/c", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "先把质量分数换算成物质的量浓度，再用稀释前后 HCl 物质的量不变。易错：把 2000 mL 当成 2000 L，或直接用 37% 当浓度。"}, {"id": "bc01_short_9", "modI": 0, "q": "【计算】某弱酸溶液浓度为 0.02 mol/L，测得 pH=4.6：(1) 求[H⁺]；(2) 求该酸的 Ka 和 pKa。", "a": "(1) pH=4.6，[H⁺]=10⁻⁴·⁶≈2.51×10⁻⁵ mol/L。\n(2) 弱酸 HA 解离：Ka≈[H⁺]²/(c−[H⁺])。\nKa≈(2.51×10⁻⁵)²/(0.02−2.51×10⁻⁵)≈3.15×10⁻⁸。\npKa=−lgKa≈7.50。", "kps": "pH→[H+]；弱酸Ka≈[H+]^2/(c−[H+])；pKa=−lgKa", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "pH 是负对数，先换成浓度；弱酸解离用 Ka=[H⁺][A⁻]/[HA]，当[H⁺]远小于 c 时可近似 c−[H⁺]≈c。"}, {"id": "bc01_short_10", "modI": 0, "q": "判断共轭酸碱对：H₂PO₄⁻/HPO₄²⁻、HCO₃⁻/CO₃²⁻、HCOOH/HCOO⁻中，哪个是共轭酸？", "a": "共轭酸是给出质子后变成对应碱的物种，即每对中多一个H⁺的成员：\n(1) H₂PO₄⁻；(2) HCO₃⁻；(3) HCOOH。\n它们分别给出H⁺后形成HPO₄²⁻、CO₃²⁻、HCOO⁻。", "kps": "共轭酸=得到质子后的形式；逐对判断", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "先找“多一个H⁺”的物种；共轭酸/共轭碱只差一个质子。"}, {"id": "bc01_short_11", "modI": 0, "q": "【计算】溶液含 0.20 mol/L 醋酸钠和 0.60 mol/L 醋酸（pKa=4.76），求 pH。", "a": "用 Henderson-Hasselbalch 方程：pH=pKa+lg([NaAc]/[HAc])。\npH=4.76+lg(0.20/0.60)=4.76+lg(1/3)=4.76−0.477≈4.28。", "kps": "Henderson-Hasselbalch：pH=pKa+lg([A−]/[HA])", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "盐浓度在分子、酸浓度在分母；比值小于 1 时 pH 低于 pKa。不要代反。"}, {"id": "bc01_short_12", "modI": 0, "q": "【计算】配制 0.2 mol/L、pH=5.0 的醋酸盐缓冲液，求所需醋酸和醋酸钠的浓度（醋酸 pKa=4.76）。", "a": "设[NaAc]=x，[HAc]=y，则 x+y=0.2 mol/L。\n由 pH=pKa+lg(x/y)：5.0=4.76+lg(x/y)，lg(x/y)=0.24，x/y≈1.74。\n联立解得 x≈0.127 mol/L，y≈0.073 mol/L。\n即醋酸钠约 0.127 mol/L，醋酸约 0.073 mol/L。", "kps": "pH=pKa+lg([盐]/[酸])；x+y=总浓度；解对数方程", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第1章笔记", "e": "先由 pH 与 pKa 求盐/酸比值，再用总浓度守恒解方程组。易错：把 x/y 写成 y/x，或忘记 x+y=0.2。"}], "calc": []};
